	"os"
)

func mod(a, n int64) int64 {
	r := a % n
	if r < 0 {
		r += n
	}
	return r
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, sx, sy, dx, dy, t int64
	fmt.Fscan(reader, &n, &sx, &sy, &dx, &dy, &t)

	x := sx
	y := sy
	curDx := dx
	curDy := dy

	for i := int64(0); i < t; i++ {
		k := (x + y) + i // bushes at time i (0-based)
		curDx += k
		curDy += k
		x = mod(x+curDx-1, n) + 1
		y = mod(y+curDy-1, n) + 1
	}

	fmt.Println(x, y)
}
